/// (types_map[True] in insertion order, suffix_map and encodings_map sorted by key) of the project's Python
pub fn tables(python: (u32, u32)) -> (&'static [(&'static str, &'static str)], &'static [(&'static str, &'static str)], &'static [(&'static str, &'static str)]) {
    match python.1 {
        ..=12 => (&TYPES_312, &SUFFIXES_312, &ENCODINGS_312),
        13 => (&TYPES_313, &SUFFIXES_313, &ENCODINGS_313),
        14 => (&TYPES_314, &SUFFIXES_314, &ENCODINGS_314),
        15.. => (&TYPES_315, &SUFFIXES_315, &ENCODINGS_315),
    }
}

/// types_map[False] (the non-strict, commonly found types) of the project's Python, in insertion order
pub fn common(python: (u32, u32)) -> &'static [(&'static str, &'static str)] {
    match python.1 {
        ..=12 => &COMMON_312,
        13 => &COMMON_313,
        14 => &COMMON_314,
        15.. => &COMMON_315,
    }
}
